// Turns the classifier's one-word answer into a safe intent value.
const raw = String($input.first().json.text || '').trim();
const m = raw.toUpperCase().match(/\b(PLAN|RISK|STATUS|MILESTONE|UNCLEAR)\b/);
const intent = m ? m[1] : 'UNCLEAR';   // anything unexpected falls back to UNCLEAR
const userRequest = $('Config').first().json.chatInput;
return [{ json: { intent, userRequest, classifierRaw: raw } }];

const req = $('Parse Intent').first().json;
const description = $('Fetch Project Description (Plan)').first().json.data;
const context = 'SOURCE: project description file (ABCDE_Ltd_project_description.txt)\n---\n' + description;
return [{ json: { intent: 'PLAN', userRequest: req.userRequest, context } }];

function parseCsv(text) {
  const rows = [];
  let row = [], cur = '', q = false;
  text = String(text || '').replace(/^\uFEFF/, '');
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"') { if (text[i + 1] === '"') { cur += '"'; i++; } else { q = false; } }
      else { cur += c; }
    } else if (c === '"') { q = true; }
    else if (c === ',') { row.push(cur); cur = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(cur); cur = '';
      if (row.some(x => x.trim() !== '')) rows.push(row);
      row = [];
    } else { cur += c; }
  }
  if (cur !== '' || row.length) { row.push(cur); if (row.some(x => x.trim() !== '')) rows.push(row); }
  const head = rows.shift().map(h => h.trim());
  return rows.map(r => Object.fromEntries(head.map((h, i) => [h, (r[i] || '').trim()])));
}
const req = $('Parse Intent').first().json;
const cfg = $('Config').first().json;
const asOf = new Date(cfg.asOfDate + 'T00:00:00Z');
const description = $('Fetch Project Description (Risk)').first().json.data;
const register = parseCsv($('Fetch Risk Register').first().json.data);
const tasks = parseCsv($('Fetch Task Board (Risk)').first().json.data);
const level = { High: 3, Medium: 2, Low: 1 };
const band = s => (s >= 6 ? 'High' : s >= 3 ? 'Medium' : 'Low');
const day = 86400000;
const daysTo = d => Math.round((new Date(d + 'T00:00:00Z') - asOf) / day);

const regLines = register.map(r => {
  const s = (level[r.likelihood] || 0) * (level[r.impact] || 0);
  return `${r.risk_id} | ${r.risk} | ${r.category} | L=${r.likelihood} | I=${r.impact} | score=${s || 'UNKNOWN'} (${s ? band(s) : 'UNKNOWN'}) | owner=${r.owner} | status=${r.status} | mitigation=${r.mitigation}`;
});
const blocked = tasks.filter(t => t.status === 'Blocked')
  .map(t => `${t.task_id} | ${t.task} | milestone ${t.milestone_id} | owner=${t.owner || 'UNASSIGNED'} | due ${t.due_date} | reason: ${t.notes || 'not stated'}`);
const overdue = tasks.filter(t => t.status !== 'Done' && daysTo(t.due_date) < 0)
  .map(t => `${t.task_id} | ${t.task} | milestone ${t.milestone_id} | ${t.status} | due ${t.due_date} | ${-daysTo(t.due_date)} days overdue`);
const unassigned = tasks.filter(t => t.status !== 'Done' && !t.owner).map(t => `${t.task_id} | ${t.task} | milestone ${t.milestone_id}`);
const open = {};
tasks.filter(t => t.status !== 'Done' && t.owner).forEach(t => { open[t.owner] = (open[t.owner] || 0) + 1; });
const load = Object.entries(open).sort((a, b) => b[1] - a[1]).map(([o, n]) => `${o}: ${n} open tasks`);

const context = [
  `AS-OF DATE: ${cfg.asOfDate}`,
  'RATING RULE: score = likelihood x impact with High=3, Medium=2, Low=1. Score 6-9 = High, 3-4 = Medium, 1-2 = Low.',
  '',
  'SOURCE A - PROJECT DESCRIPTION:\n' + description,
  '',
  'SOURCE B - EXISTING RISK REGISTER (risk_id | risk | category | likelihood | impact | score | owner | status | mitigation):\n' + regLines.join('\n'),
  '',
  'SOURCE C - TASK BOARD EVIDENCE',
  'Blocked tasks:\n' + (blocked.join('\n') || 'none'),
  'Overdue open tasks:\n' + (overdue.join('\n') || 'none'),
  'Open tasks without an owner:\n' + (unassigned.join('\n') || 'none'),
  'Open task load per owner:\n' + (load.join('\n') || 'none'),
  '',
  'NOT AVAILABLE IN THE DATA: actual spend, cost forecasts, effort hours, vendor contract terms, defect counts.'
].join('\n');
return [{ json: { intent: 'RISK', userRequest: req.userRequest, context } }];

