const req = $('Parse Intent').first().json;
const cfg = $('Config').first().json;
const asOf = new Date(cfg.asOfDate + 'T00:00:00Z');
const tasks = parseCsv($('Fetch Task Board (Status)').first().json.data);
const day = 86400000;
const daysTo = d => Math.round((new Date(d + 'T00:00:00Z') - asOf) / day);

const total = tasks.length;
const counts = {};
tasks.forEach(t => { counts[t.status] = (counts[t.status] || 0) + 1; });
const done = counts['Done'] || 0;
const pct = total ? Math.round((done / total) * 100) : 0;
const fmt = t => `${t.task_id} | ${t.task} | milestone ${t.milestone_id} | owner=${t.owner || 'UNASSIGNED'} | status=${t.status} | due ${t.due_date}`;

const blocked = tasks.filter(t => t.status === 'Blocked').map(t => fmt(t) + ` | reason: ${t.notes || 'not stated'}`);
const overdue = tasks.filter(t => t.status !== 'Done' && daysTo(t.due_date) < 0).map(t => fmt(t) + ` | ${-daysTo(t.due_date)} days overdue`);
const next7 = tasks.filter(t => t.status !== 'Done' && daysTo(t.due_date) >= 0 && daysTo(t.due_date) <= 7).map(t => fmt(t) + ` | due in ${daysTo(t.due_date)} days`);
const inProgress = tasks.filter(t => t.status === 'In Progress').map(fmt);
const unassigned = tasks.filter(t => t.status !== 'Done' && !t.owner).map(fmt);
const owners = {};
tasks.forEach(t => {
  const o = t.owner || 'UNASSIGNED';
  owners[o] = owners[o] || { Done: 0, 'In Progress': 0, Blocked: 0, 'To Do': 0 };
  owners[o][t.status] = (owners[o][t.status] || 0) + 1;
});
const ownerLines = Object.entries(owners).map(([o, c]) => `${o}: Done ${c['Done']}, In Progress ${c['In Progress']}, Blocked ${c['Blocked']}, To Do ${c['To Do']}`);

const context = [
  `AS-OF DATE: ${cfg.asOfDate}`,
  'ALL NUMBERS BELOW WERE COMPUTED BY CODE FROM THE TASK BOARD. Copy them exactly. Do not recalculate.',
  '',
  `TOTAL TASKS: ${total}`,
  `COUNTS BY STATUS: Done ${done}, In Progress ${counts['In Progress'] || 0}, Blocked ${counts['Blocked'] || 0}, To Do ${counts['To Do'] || 0}`,
  `COMPLETION: ${done} of ${total} tasks Done (${pct}%)`,
  `OVERDUE OPEN TASKS: ${overdue.length}`,
  '',
  'BLOCKED TASKS:\n' + (blocked.join('\n') || 'none'),
  'OVERDUE OPEN TASKS:\n' + (overdue.join('\n') || 'none'),
  'DUE IN THE NEXT 7 DAYS (not Done):\n' + (next7.join('\n') || 'none'),
  'IN PROGRESS:\n' + (inProgress.join('\n') || 'none'),
  'OPEN TASKS WITHOUT AN OWNER:\n' + (unassigned.join('\n') || 'none'),
  'TASKS PER OWNER:\n' + ownerLines.join('\n'),
  '',
  'NOT AVAILABLE IN THE DATA: budget or spend, effort hours, actual start dates, story points, defect counts, any project other than ABCDE Ltd.'
].join('\n');
return [{ json: { intent: 'STATUS', userRequest: req.userRequest, context } }];

