const req = $('Parse Intent').first().json;
const cfg = $('Config').first().json;
const asOf = new Date(cfg.asOfDate + 'T00:00:00Z');
const day = 86400000;
const daysTo = d => Math.round((new Date(d + 'T00:00:00Z') - asOf) / day);
const ms = parseCsv($('Fetch Timeline').first().json.data).sort((a, b) => a.due_date.localeCompare(b.due_date));
const tasks = parseCsv($('Fetch Task Board (Milestone)').first().json.data);

// Step 1: own status of each milestone from its linked tasks
const info = {};
ms.forEach(m => {
  const t = tasks.filter(x => x.milestone_id === m.milestone_id);
  const done = t.filter(x => x.status === 'Done').length;
  const blocked = t.filter(x => x.status === 'Blocked');
  const overdue = t.filter(x => x.status !== 'Done' && daysTo(x.due_date) < 0);
  const dtd = daysTo(m.due_date);
  const pct = t.length ? Math.round((done / t.length) * 100) : null;
  let rag, reasons = [];
  if (!t.length) { rag = 'UNKNOWN'; reasons.push('no tasks linked to this milestone'); }
  else if (done === t.length) { rag = 'COMPLETE'; }
  else {
    if (dtd < 0) reasons.push(`milestone date passed ${-dtd} days ago and it is not complete`);
    if (overdue.length) reasons.push(`${overdue.length} overdue task(s): ${overdue.map(x => x.task_id).join(', ')}`);
    if (blocked.length) reasons.push(`${blocked.length} blocked task(s): ${blocked.map(x => x.task_id + ' (' + (x.notes || 'reason not stated') + ')').join('; ')}`);
    if (dtd < 0 || overdue.length || (blocked.length && dtd <= 30)) rag = 'RED';
    else if (blocked.length || (dtd <= 30 && pct < 60)) rag = 'AMBER';
    else rag = 'GREEN';
    if (dtd <= 30 && pct < 60 && rag !== 'RED') reasons.push(`due in ${dtd} days with only ${pct}% of tasks done`);
  }
  info[m.milestone_id] = { m, t, done, pct, dtd, rag, reasons };
});

// Step 2: downstream impact - any milestone that depends (directly or indirectly) on a RED milestone
const deps = id => (info[id].m.depends_on || '').split(';').map(s => s.trim()).filter(Boolean).filter(x => info[x]);
const upstreamRed = (id, seen = new Set()) => {
  let out = [];
  deps(id).forEach(d => {
    if (seen.has(d)) return; seen.add(d);
    if (info[d].rag === 'RED') out.push(d);
    out = out.concat(upstreamRed(d, seen));
  });
  return [...new Set(out)];
};
ms.forEach(m => {
  const i = info[m.milestone_id];
  const up = upstreamRed(m.milestone_id);
  if (up.length && i.rag !== 'COMPLETE') {
    i.reasons.push('depends on RED milestone(s): ' + up.join(', '));
    if (i.rag === 'GREEN' || i.rag === 'UNKNOWN') i.rag = 'AMBER';
  }
});

const lines = ms.map(m => {
  const i = info[m.milestone_id];
  return `${m.milestone_id} | ${m.milestone} | phase=${m.phase} | due ${m.due_date} (${i.dtd >= 0 ? 'in ' + i.dtd + ' days' : -i.dtd + ' days ago'}) | owner=${m.owner} | tasks done ${i.done}/${i.t.length}${i.pct === null ? '' : ' (' + i.pct + '%)'} | RAG=${i.rag}${i.reasons.length ? ' | reasons: ' + i.reasons.join(' ; ') : ''}`;
});
const counts = {};
ms.forEach(m => { const r = info[m.milestone_id].rag; counts[r] = (counts[r] || 0) + 1; });

const context = [
  `AS-OF DATE: ${cfg.asOfDate}`,
  'RAG RULES (applied by code, do not change them):',
  '- COMPLETE: every linked task is Done.',
  '- RED: milestone date passed and not complete, OR any linked task overdue, OR a blocked task and the milestone is due within 30 days.',
  '- AMBER: a blocked task, OR due within 30 days with under 60% of tasks done, OR depends on a RED milestone.',
  '- GREEN: none of the above. UNKNOWN: no tasks linked.',
  '',
  `SUMMARY: ${Object.entries(counts).map(([k, v]) => k + ' ' + v).join(', ')}`,
  'MILESTONES (id | name | phase | due | owner | task progress | RAG | reasons):',
  lines.join('\n'),
  '',
  'NOT AVAILABLE IN THE DATA: budget impact, effort estimates, vendor commitments, any milestone not listed above.'
].join('\n');
return [{ json: { intent: 'MILESTONE', userRequest: req.userRequest, context } }];

// Builds a Langfuse ingestion payload (trace + one generation per LLM call).
const cfg = $('Config').first().json;
const pi = $('Parse Intent').first().json;
const output = $('Final Response').first().json.output;
const agents = {
  'Prepare Plan Context': ['plan-generator', 'gpt-4.1-mini'],
  'Prepare Risk Context': ['risk-analyst', 'gpt-4.1-mini'],
  'Prepare Status Context': ['status-reporter', 'gpt-4o-mini'],
  'Prepare Milestone Context': ['milestone-analyst', 'gpt-4o-mini']
};
let ctx = null, agent = null, model = null;
for (const [node, [a, m]] of Object.entries(agents)) {
  try { const it = $(node).first(); if (it && it.json && it.json.context) { ctx = it.json; agent = a; model = m; break; } } catch (e) { /* branch not executed */ }
}
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 3 | 8)).toString(16); });
const now = new Date().toISOString();
const start = cfg.startedAt || now;
const traceId = uuid();
const batch = [
  { id: uuid(), type: 'trace-create', timestamp: now, body: { id: traceId, name: 'mira-request', timestamp: start, sessionId: cfg.sessionId, input: pi.userRequest, output, tags: ['mira', 'capstone', pi.intent], metadata: { intent: pi.intent, routedTo: agent || 'clarification-no-llm' } } },
  { id: uuid(), type: 'generation-create', timestamp: now, body: { id: uuid(), traceId, name: 'intent-classifier', model: 'gpt-4o-mini', input: pi.userRequest, output: pi.classifierRaw, startTime: start, endTime: now } }
];
if (ctx) {
  batch.push({ id: uuid(), type: 'generation-create', timestamp: now, body: { id: uuid(), traceId, name: agent, model, input: 'USER REQUEST: ' + ctx.userRequest + '\n\n' + ctx.context, output, startTime: start, endTime: now } });
}
return [{ json: { payload: { batch } } }];
